// List new files in the inbox folder and base64-encode each one as a plain
// JSON field (not n8n's binary-data channel, whose helper API has moved
// between versions) - only core Node.js fs/path is used, nothing n8n-specific.
const fs = require('fs');
const path = require('path');

const dir = 'C:\\n8n\\invoice\\inbox';
if (!fs.existsSync(dir)) { return []; }

const files = fs.readdirSync(dir).filter((f) => /\.(pdf|png|jpe?g)$/i.test(f));
const now = Date.now();
const out = [];

for (const f of files) {
  const full = path.join(dir, f);
  const stat = fs.statSync(full);
  // skip files still being written/copied
  if (now - stat.mtimeMs < 10000) { continue; }

  const buf  = fs.readFileSync(full);
  const ext  = path.extname(f).toLowerCase();
  const mime = ext === '.pdf' ? 'application/pdf' : ext === '.png' ? 'image/png' : 'image/jpeg';
  const base64 = buf.toString('base64');

  out.push({ json: { source_path: full, file_name: f, mime_type: mime, base64 } });
}

return out;

// Build the Gemini request body (base64 file + extraction prompt).
const prompt = 'You are an invoice parser. Return ONLY minified JSON, no markdown. Schema:\n{"vendor":string,"invoice_no":string,"invoice_date":"YYYY-MM-DD","currency":string,"lines":[{"description":string,"guest_or_ref":string,"service_date":"YYYY-MM-DD"|null,"reservation_code":string|null,"amount":number}]}\nRules: amount is a plain number (no thousands separators). guest_or_ref = the guest name or booking reference the line is for. If a line is a discount, rebate, or adjustment that applies to another line (e.g. a room charge), give it the SAME guest_or_ref and reservation_code as that line, and make amount negative. Do not invent a discount that is not printed on the invoice. If a line has no own date, leave service_date null.';

const body = {
  contents: [{
    parts: [
      { inline_data: { mime_type: $json.mime_type || 'application/pdf', data: $json.base64 } },
      { text: prompt },
    ],
  }],
  generationConfig: { response_mime_type: 'application/json' },
};

return { json: { geminiBody: JSON.stringify(body), source_path: $json.source_path, file_name: $json.file_name } };

// Parse Gemini's JSON text, NET discount/adjustment lines into the booking
// they apply to (the review API rejects a negative cost - and matching is
// per booking anyway, not per invoice line), then shape into the
// /purchase/lines/review payload.
const prior = $('Build Gemini Request').item.json;
const text  = $json.candidates[0].content.parts[0].text;
const inv   = JSON.parse(text);

const norm = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
const groups = new Map();

for (const l of (inv.lines || [])) {
  const key = norm(l.reservation_code) || norm(l.guest_or_ref) || norm(l.description);
  const amount = Number(String(l.amount ?? 0).replace(/[^0-9.-]/g, ''));
  if (!groups.has(key)) {
    groups.set(key, {
      party_name: l.guest_or_ref || l.description || '',
      service_date: l.service_date || null,
      res_code: l.reservation_code || null,
      descriptions: [],
      cost: 0,
    });
  }
  const g = groups.get(key);
  g.cost += amount;
  if (l.description) { g.descriptions.push(l.description); }
  if (!g.service_date && l.service_date) { g.service_date = l.service_date; }
}

const items = Array.from(groups.values())
  .filter((g) => g.cost >= 0) // a group that still nets negative is a data problem, not a booking - drop it, don't send an invalid cost
  .map((g) => ({
    supplier: inv.vendor || '',
    service_date: g.service_date || inv.invoice_date || null,
    party_name: g.party_name,
    description: g.descriptions.join(' + '),
    res_code: g.res_code || undefined,
    cost: Math.round(g.cost * 100) / 100,
    supplier_invoice_ref: inv.invoice_no || undefined,
    supplier_invoice_date: inv.invoice_date || undefined,
  }));

return {
  json: {
    vendor: inv.vendor || '',
    file_name: prior.file_name,
    source_path: prior.source_path,
    items,
  },
};

// Move the processed file out of inbox\ so the next poll doesn't see it again.
const fs = require('fs');
const path = require('path');

const prev = $('Parse & Build Review Payload').item.json;
const destDir = 'C:\\n8n\\invoice\\queued';
if (!fs.existsSync(destDir)) { fs.mkdirSync(destDir, { recursive: true }); }
const dest = path.join(destDir, path.basename(prev.source_path));
fs.renameSync(prev.source_path, dest);

return { json: { moved_to: dest, batch_response: $json } };
